package br.com.fiap.bank.core.presentation;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import jakarta.validation.Valid; import java.util.*; import br.com.fiap.bank.core.application.BankService; import br.com.fiap.bank.core.application.dto.*; @RestController @RequestMapping("/api/v1/contas") public class ContaController { private final BankService service; public ContaController(BankService s){service=s;} @GetMapping public List<ContaResponse> all(){return service.contas();} @GetMapping("/{numero}") public ContaResponse get(@PathVariable String numero){return service.conta(numero);} @GetMapping("/cliente/{cpf}") public ContaResponse cpf(@PathVariable String cpf){return service.contaCpf(cpf);} @PostMapping public ResponseEntity<ContaResponse> create(@Valid @RequestBody CriarContaRequest r){return ResponseEntity.status(201).body(service.abrir(r));} @PutMapping("/{numero}/saldo") public ContaResponse saldo(@PathVariable String numero,@Valid @RequestBody AtualizarSaldoRequest r){return service.saldo(numero,r);} @DeleteMapping("/{numero}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable String numero){service.encerrar(numero);} }
